operations.schema:
input SetAssociationNameInput {
  nameEn: String!
  nameDe: String
}

input SetAssociationSeatInput {
  seatCity: String!
  seatCanton: String!
  registeredAddress: String
}

operations.reducer:
state.seatCity = action.input.seatCity;
state.seatCanton = action.input.seatCanton;
if (action.input.registeredAddress) {
  state.registeredAddress = action.input.registeredAddress;
  state.registeredAddressConfirmed = true;
}

operations.schema:
input SetFoundingDateInput {
  foundingDate: Date!
}

input SetFiscalDetailsInput {
  fiscalYearEnd: String
  membershipFee: String
  primaryLanguage: PrimaryLanguage
}

operations.reducer:
if (action.input.fiscalYearEnd) state.fiscalYearEnd = action.input.fiscalYearEnd;
if (action.input.membershipFee) state.membershipFee = action.input.membershipFee;
if (action.input.primaryLanguage) state.primaryLanguage = action.input.primaryLanguage;

operations.schema:
input SetPurposeInput {
  purposeEn: String!
  purposeDe: String
}

operations.reducer:
const member = {
  id: action.input.id,
  type: action.input.type,
  name: action.input.name,
  nationalityOrCountry: action.input.nationalityOrCountry,
  residenceOrCity: action.input.residenceOrCity,
  representative: action.input.representative || null,
};
state.members.push(member);
state.belowRecommendedMemberCount = state.members.length < 3;
updatePersonalunionFlag(state);

const idx = state.members.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new MemberNotFoundError(`Member ${action.input.id} not found`);
const member = state.members[idx];
if (action.input.type) member.type = action.input.type;
if (action.input.name) member.name = action.input.name;
if (action.input.nationalityOrCountry) member.nationalityOrCountry = action.input.nationalityOrCountry;
if (action.input.residenceOrCity) member.residenceOrCity = action.input.residenceOrCity;
if (action.input.representative !== undefined && action.input.representative !== null) member.representative = action.input.representative;
updatePersonalunionFlag(state);

operations.schema:
input RemoveMemberInput {
  id: OID!
}

operations.reducer:
const idx = state.members.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new MemberNotFoundError(`Member ${action.input.id} not found`);
state.members.splice(idx, 1);
state.belowRecommendedMemberCount = state.members.length < 3;
updatePersonalunionFlag(state);

if (!state.boardMembers) state.boardMembers = [];
const boardMember = {
  id: action.input.id,
  type: action.input.type,
  name: action.input.name,
  nationalityOrCountry: action.input.nationalityOrCountry,
  residenceOrCity: action.input.residenceOrCity,
  representative: action.input.representative || null,
};
state.boardMembers.push(boardMember);
updatePersonalunionFlag(state);

if (!state.boardMembers) state.boardMembers = [];
const idx = state.boardMembers.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new BoardMemberNotFoundError(`Board member ${action.input.id} not found`);
const member = state.boardMembers[idx];
if (action.input.type) member.type = action.input.type;
if (action.input.name) member.name = action.input.name;
if (action.input.nationalityOrCountry) member.nationalityOrCountry = action.input.nationalityOrCountry;
if (action.input.residenceOrCity) member.residenceOrCity = action.input.residenceOrCity;
if (action.input.representative !== undefined && action.input.representative !== null) member.representative = action.input.representative;
updatePersonalunionFlag(state);

operations.schema:
input RemoveBoardMemberInput {
  id: OID!
}

operations.reducer:
if (!state.boardMembers) state.boardMembers = [];
const idx = state.boardMembers.findIndex((m) => m.id === action.input.id);
if (idx === -1) throw new BoardMemberNotFoundError(`Board member ${action.input.id} not found`);
state.boardMembers.splice(idx, 1);
updatePersonalunionFlag(state);

operations.schema:
input CopyFoundingMembersToBoardInput {
  confirm: Boolean!
}

operations.reducer:
state.boardMembers = state.members.map((member) => ({
  id: member.id,
  type: member.type,
  name: member.name,
  nationalityOrCountry: member.nationalityOrCountry,
  residenceOrCity: member.residenceOrCity,
  representative: member.representative || null,
}));
updatePersonalunionFlag(state);

operations.schema:
input SetMeetingRolesInput {
  chairName: String!
  chairRole: String!
  secretaryName: String!
  secretaryRole: String!
}

operations.reducer:
state.chairName = action.input.chairName;
state.chairRole = action.input.chairRole;
state.secretaryName = action.input.secretaryName;
state.secretaryRole = action.input.secretaryRole;

operations.schema:
input StartStage_2Input {
  startedAt: DateTime!
}

input SetStage2DocumentMarkdownInput {
  documentType: Stage2DocumentType!
  markdown: String!
}

operations.reducer:
const target = action.input.documentType === "AOA" ? (state.aoaDocument || (state.aoaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "FOUNDING_MINUTES" ? (state.foundingMinutesDocument || (state.foundingMinutesDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "REG_GA" ? (state.regGaDocument || (state.regGaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : (state.mpaDocument || (state.mpaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false}));
if (target.isLocked) return;
target.markdown = action.input.markdown;

operations.schema:
input MarkStage2DocumentSignedInput {
  documentType: Stage2DocumentType!
  signedAt: DateTime!
}

operations.reducer:
const target = action.input.documentType === "AOA" ? (state.aoaDocument || (state.aoaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "FOUNDING_MINUTES" ? (state.foundingMinutesDocument || (state.foundingMinutesDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : action.input.documentType === "REG_GA" ? (state.regGaDocument || (state.regGaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false})) : (state.mpaDocument || (state.mpaDocument = {markdown: null, isSigned: false, signedAt: null, isLocked: false}));
if (target.isLocked) return;
target.isSigned = true;
target.signedAt = action.input.signedAt;
target.isLocked = true;
if (state.aoaDocument?.isSigned && state.foundingMinutesDocument?.isSigned && !state.incorporationCompletedAt) {
  state.incorporationCompletedAt = action.input.signedAt;
}

const phase = state.phases.find((p) => p.phaseNumber === action.input.phaseNumber);
if (!phase) throw new PhaseNotFoundError(`Phase ${action.input.phaseNumber} not found`);
phase.status = action.input.status;
if (action.input.documentsGenerated !== undefined && action.input.documentsGenerated !== null) phase.documentsGenerated = action.input.documentsGenerated;
if (action.input.documentsSigned !== undefined && action.input.documentsSigned !== null) phase.documentsSigned = action.input.documentsSigned;
if (action.input.completedDate) phase.completedDate = action.input.completedDate;

operations.schema:
input AdvancePhaseInput {
  completedDate: Date!
}

operations.reducer:
const current = state.phases.find((p) => p.phaseNumber === state.currentPhase);
if (!current) throw new PhaseNotFoundError(`Current phase ${state.currentPhase} not found`);
current.status = "COMPLETE";
current.completedDate = action.input.completedDate;
const next = state.phases.find((p) => p.phaseNumber === (state.currentPhase ?? 0) + 1);
if (next) {
  next.status = "IN_PROGRESS";
  state.currentPhase = next.phaseNumber;
}

operations.schema:
input AddNoteInput {
  note: String!
}
